def register_all_namespaces(xml_text):
    # Register every xmlns prefix declared on the root element so the
    # serialized output keeps the original prefixes (notably w:).
    root_tag = xml_text[:xml_text.find('>', xml_text.find('<', 1)) + 1]
    for pref, uri in re.findall(r'xmlns:([A-Za-z0-9]+)="([^"]+)"', root_tag):
        ET.register_namespace(pref, uri)
    for uri, in re.findall(r'xmlns="([^"]+)"', root_tag):
        ET.register_namespace('', uri)


def process_part(xml_bytes, mapping, relocation_keep, stats):
    xml_text = xml_bytes.decode('utf-8')
    register_all_namespaces(xml_text)
    root = ET.fromstring(xml_bytes)
    for p in list(iter_paragraphs(root)):
        process_paragraph(p, mapping, relocation_keep, stats)
    body = ET.tostring(root, encoding='unicode')
    return body
